class Solution {
public:
    long long minimumFuelCost(std::vector<std::vector<int>>& roads, int seats) {
        int n = roads.size() + 1;
        std::vector<std::vector<int>> adj(n);
        for (const auto& r : roads) {
            adj[r[0]].push_back(r[1]);
            adj[r[1]].push_back(r[0]);
        }
        long long fuel = 0;
        auto dfs = [&](auto& self, int u, int p) -> long long {
            long long people = 1;
            for (int v : adj[u]) {
                if (v != p) people += self(self, v, u);
            }
            if (u != 0) fuel += (people + seats - 1) / seats;
            return people;
        };
        dfs(dfs, 0, -1);
        return fuel;
    }
};

class Solution {
    private long fuel = 0;
    public long minimumFuelCost(int[][] roads, int seats) {
        int n = roads.length + 1;
        java.util.List<Integer>[] adj = new java.util.ArrayList[n];
        for (int i = 0; i < n; i++) adj[i] = new java.util.ArrayList<>();
        for (int[] r : roads) {
            adj[r[0]].add(r[1]);
            adj[r[1]].add(r[0]);
        }
        fuel = 0;
        dfs(0, -1, adj, seats);
        return fuel;
    }
    private long dfs(int u, int p, java.util.List<Integer>[] adj, int seats) {
        long people = 1;
        for (int v : adj[u]) {
            if (v != p) people += dfs(v, u, adj, seats);
        }
        if (u != 0) fuel += (people + seats - 1) / seats;
        return people;
    }
}

var minimumFuelCost = function(roads, seats) {
    const n = roads.length + 1;
    const adj = Array.from({ length: n }, () => []);
    for (const [u, v] of roads) {
        adj[u].push(v);
        adj[v].push(u);
    }
    let fuel = 0;
    const dfs = (u, p) => {
        let people = 1;
        for (const v of adj[u]) {
            if (v !== p) people += dfs(v, u);
        }
        if (u !== 0) fuel += Math.ceil(people / seats);
        return people;
    };
    dfs(0, -1);
    return fuel;
